(async () => {
  const owner = 'DoshideDK';
  const repo = 'JS-Slash-Runner';
  const pluginPath = '%E4%B8%96%E7%95%8C%E4%B9%A6%E7%AE%A1%E7%90%86%E5%99%A8.js';

  const probeUrl = `https://cdn.jsdelivr.net/gh/${owner}/${repo}@latest/${pluginPath}?t=${Date.now()}`;
  const probe = await fetch(probeUrl, {
    method: 'HEAD',
    cache: 'no-store',
  });

  if (!probe.ok) {
    throw new Error(`[世界书管理器] 探测最新版本失败: ${probe.status}`);
  }

  const version = probe.headers.get('x-jsd-version');
  if (!version) {
    throw new Error('[世界书管理器] 响应头里没有 x-jsd-version');
  }

  console.log('[世界书管理器] loader tag:', version);

  await import(`https://cdn.jsdelivr.net/gh/${owner}/${repo}@${version}/${pluginPath}`);
})();
